{{(() => {
  const en = appsmith.store.bo_lang === 'en';
  const items = GetOrderItems.data || [];
  const n = (x) => { const v = Number(String(x ?? '').replace(',', '.')); return v > 0 ? v : null; };
  const f = (v, d) => String(Math.round(v * Math.pow(10, d)) / Math.pow(10, d)).replace('.', ',');
  const pieces = items.reduce((s, i) => s + (Number(i.quantity) || 0), 0);
  const lines = [(en ? 'Pieces: ' : 'Общо бройки: ') + pieces];
  const weighed = items.length > 0 && items.every((i) => n(i.weight) !== null);
  if (weighed) {
    const kg = items.reduce((s, i) => s + n(i.weight) * (Number(i.quantity) || 1), 0);
    lines.push((en ? 'Total weight: ' : 'Общо тегло: ') + f(kg, 3) + (en ? ' kg' : ' кг'));
  }
  const sized = items.length > 0 && items.every((i) => n(i.length) !== null && n(i.width) !== null && n(i.height) !== null);
  if (sized) {
    let vol = 0, big = null, bigVol = -1;
    items.forEach((i) => {
      const u = n(i.length) * n(i.width) * n(i.height);
      vol += u * (Number(i.quantity) || 1);
      if (u > bigVol) { bigVol = u; big = [i.length, i.width, i.height].map((x) => f(n(x), 1)).join('×'); }
    });
    lines.push((en ? 'Total volume: ' : 'Общ обем: ') + f(Math.max(0.001, vol / 1000000), 3) + ' м³');
    lines.push((en ? 'Largest item: ' : 'Най-голям: ') + big + (en ? ' cm' : ' см'));
  }
  return lines.join('\n');
})()}}
